function renderServerLoginHtml(env, error = "", returnTo = "/?legacy=1") {
  const title = escapeHtml(appName(env));
  const safeReturnTo = safeAdminReturnPath(returnTo, "/?legacy=1");
  return `<!doctype html>
<html lang="ko"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"/><title>${title}</title>
<style>
body{margin:0;background:#f5f7fb;color:#111827;font-family:system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.wrap{max-width:440px;margin:8vh auto;padding:20px}.card{background:#fff;border:1px solid #e5e7eb;border-radius:18px;box-shadow:0 12px 30px rgba(15,23,42,.08);padding:24px}h1{margin:0 0 8px;font-size:28px}.muted{color:#64748b;font-size:14px}.error{background:#fef2f2;color:#b91c1c;border:1px solid #fecaca;border-radius:12px;padding:10px;margin:12px 0}input,button{font:inherit;border-radius:12px}input{width:100%;box-sizing:border-box;border:1px solid #cbd5e1;padding:13px;margin:14px 0}button{width:100%;border:0;background:#2563eb;color:#fff;font-weight:800;padding:13px;cursor:pointer}.hint{margin-top:14px;color:#64748b;font-size:13px;line-height:1.5}</style>
</head><body><main class="wrap"><section class="card"><h1>${title}</h1><p class="muted">관리자 비밀번호를 입력하세요. 인증 후 요청한 화면으로 돌아갑니다.</p>${error ? `<div class="error">${escapeHtml(error)}</div>` : ""}<form method="post" action="/login"><input type="hidden" name="return_to" value="${escapeHtml(safeReturnTo)}"/><input name="password" type="password" autocomplete="current-password" placeholder="관리자 비밀번호" autofocus required/><button type="submit">인증하고 계속</button></form><div class="hint">인증이 완료되면 보던 설정 화면을 다시 찾을 필요 없이 자동으로 복귀합니다.</div></section></main></body></html>`;
}

